# =============================================================================
# Chapter 4 figures: Correlation and Simple Linear Regression
#
# Run from the project root:
#   Rscript r_code/figures/chapter_04.R
#
# Figure 4.1 is illustrative and uses no dataset. Figures 4.2 and 4.3 use the
# 143 countries in happy_planet_index_2024.csv with a non-missing
# GDPperCapita. Captions and alt text live here, next to the code.
# figures/chapter_04/figures.yml is generated by save_book_fig(); do not edit
# it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(readr)
  library(scales)
})

assert_book_font()

# ---- Data -------------------------------------------------------------------

hp <- read_csv(
  "data/happy_planet_index_2024.csv", show_col_types = FALSE
)
hp_complete <- hp[!is.na(hp$GDPperCapita), ]

# ---- Figure 4.1: exponential growth and decay -------------------------------

# Illustrative curves. No dataset is used. The dashed straight line joins the
# endpoints of each curve, making the departure from linearity visible.
x <- seq(0, 10, length.out = 101)

growth <- data.frame(panel = "Exponential growth", x = x, curve = exp(0.55 * x))
decay <- data.frame(panel = "Exponential decay", x = x, curve = exp(-0.55 * x))

add_chord <- function(df) {
  df$linear <- df$curve[1] +
    (df$curve[nrow(df)] - df$curve[1]) *
    (df$x - df$x[1]) / (df$x[nrow(df)] - df$x[1])
  df
}
growth <- add_chord(growth)
decay <- add_chord(decay)

curve_long <- rbind(
  data.frame(
    panel = growth$panel, x = growth$x,
    form = "Curve", value = growth$curve
  ),
  data.frame(
    panel = growth$panel, x = growth$x,
    form = "Straight line", value = growth$linear
  ),
  data.frame(
    panel = decay$panel, x = decay$x,
    form = "Curve", value = decay$curve
  ),
  data.frame(
    panel = decay$panel, x = decay$x,
    form = "Straight line", value = decay$linear
  )
)
curve_long$panel <- factor(
  curve_long$panel, levels = c("Exponential growth", "Exponential decay")
)
curve_long$form <- factor(
  curve_long$form, levels = c("Curve", "Straight line")
)

p41 <- ggplot(
  curve_long, aes(x = x, y = value, colour = form, linetype = form)
) +
  geom_line(linewidth = 0.9) +
  facet_wrap(~ panel, scales = "free_y") +
  scale_colour_manual(
    values = c(
      "Curve" = book_palette[["blue"]],
      "Straight line" = BOOK_MUTED
    ),
    name = NULL
  ) +
  scale_linetype_manual(
    values = c("Curve" = "solid", "Straight line" = "dashed"),
    name = NULL
  ) +
  labs(x = "Time", y = "Amount") +
  book_theme()

save_book_fig(
  p41,
  chapter = 4, id = "4.1", type = "line", slug = "exponential_growth_decay",
  caption = paste(
    "Illustrative exponential growth and decay curves, each compared with a",
    "straight line through its endpoints. Both curves bend away from the",
    "straight line, so a straight-line model would fit poorly."
  ),
  alt = paste(
    "Two side-by-side line charts. The left panel shows a curve that rises",
    "slowly and then steeply, labeled exponential growth, below a dashed",
    "straight line through its endpoints. The right panel shows a curve that",
    "drops steeply and then flattens, labeled exponential decay, also below",
    "the dashed straight line."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "These curves are illustrative; no dataset is used. They show the shape",
    "of exponential growth and decay, not observed values."
  )
)

# ---- Figure 4.2: GDP per capita and life expectancy ------------------------

p42 <- ggplot(
  hp_complete, aes(x = GDPperCapita, y = LifeExpectancy)
) +
  geom_point(
    shape = 21, size = 1.8, fill = book_palette[["blue"]],
    colour = BOOK_INK, stroke = 0.25, alpha = 0.7
  ) +
  scale_x_continuous(
    labels = label_comma(), expand = expansion(mult = c(0.01, 0.06))
  ) +
  labs(x = "GDP per capita", y = "Life expectancy (years)") +
  book_theme()

save_book_fig(
  p42,
  chapter = 4, id = "4.2", type = "scatter",
  slug = "gdp_life_expectancy_curve",
  caption = paste(
    "GDP per capita and life expectancy for 143 countries. Life expectancy",
    "rises steeply at low incomes and then levels off, the pattern called",
    "diminishing returns."
  ),
  alt = paste(
    "Scatterplot of GDP per capita versus life expectancy for 143 countries.",
    "Points rise steeply from the mid-50s at the lowest incomes and then",
    "flatten near 80 years at higher incomes."
  ),
  author_note = paste(
    "This scatterplot repeats Figure 1.7 with the same variables. It is",
    "included here to show the curved relationship before the log",
    "transformation."
  )
)

# ---- Figure 4.3: footprint regression with intervals -----------------------

foot_model <- lm(Footprint ~ GDPperCapita, data = hp_complete)

x_seq <- seq(0, 120000, length.out = 200)
band <- data.frame(GDPperCapita = x_seq)
ci <- predict(foot_model, band, interval = "confidence")
pi <- predict(foot_model, band, interval = "prediction")
band$fit <- ci[, "fit"]
band$ci_lwr <- ci[, "lwr"]
band$ci_upr <- ci[, "upr"]
band$pi_lwr <- pi[, "lwr"]
band$pi_upr <- pi[, "upr"]

p43 <- ggplot() +
  geom_ribbon(
    data = band,
    aes(
      x = GDPperCapita, ymin = pi_lwr, ymax = pi_upr,
      fill = "95% prediction interval"
    ),
    alpha = 0.18, colour = NA
  ) +
  geom_ribbon(
    data = band,
    aes(
      x = GDPperCapita, ymin = ci_lwr, ymax = ci_upr,
      fill = "95% confidence interval"
    ),
    alpha = 0.35, colour = NA
  ) +
  geom_point(
    data = hp_complete, aes(x = GDPperCapita, y = Footprint),
    shape = 21, size = 1.6, fill = book_palette[["blue"]],
    colour = BOOK_INK, stroke = 0.25, alpha = 0.55
  ) +
  geom_line(
    data = band, aes(x = GDPperCapita, y = fit),
    colour = BOOK_INK, linewidth = 0.9
  ) +
  scale_fill_manual(
    values = c(
      "95% prediction interval" = book_palette[["orange"]],
      "95% confidence interval" = book_palette[["sky_blue"]]
    ),
    name = NULL
  ) +
  scale_x_continuous(labels = label_comma()) +
  coord_cartesian(xlim = c(0, 120000), ylim = c(0, 45)) +
  labs(x = "GDP per capita", y = "Ecological footprint") +
  book_theme()

save_book_fig(
  p43,
  chapter = 4, id = "4.3", type = "scatter",
  slug = "footprint_regression_intervals",
  caption = paste(
    "Simple linear regression of ecological footprint on GDP per capita for",
    "143 countries. The dark line is the fitted regression. The narrow band",
    "is the 95% confidence interval for the mean footprint; the wide band is",
    "the 95% prediction interval for an individual country."
  ),
  alt = paste(
    "Scatterplot of ecological footprint against GDP per capita for 143",
    "countries, with a rising regression line. A narrow shaded band hugs the",
    "line and a much wider shaded band surrounds it, widening at higher",
    "incomes."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "The model uses the 143 countries with a non-missing GDPperCapita. The",
    "prediction interval extends below zero at the lowest incomes, which is",
    "not physically possible for a footprint, so the y-axis starts at zero."
  )
)
